import { z } from "zod";
import { route } from "@/lib/api";
import { HttpError, databaseError, json, readJson } from "@/lib/http";
import { userDb } from "@/lib/supabase/server";
import { adminDb } from "@/lib/supabase/admin";
import { verifyOnboardingNonce } from "@/lib/auth/nonce";

export const dynamic = "force-dynamic";
const body = z.object({
  companyName: z.string().trim().min(2).max(200),
  consent: z.literal(true),
  nonce: z.string().min(10).max(200),
}).strict();

// Verified Auth session without profile → provision_tenant (trusted server). Tenant UUID is
// generated by PostgreSQL; role is always hr_admin of the new tenant; repeat returns the same tenant.
export const POST = route(async (request) => {
  const input = body.parse(await readJson(request, 4096));
  const db = await userDb();
  const { data: auth, error } = await db.auth.getUser();
  if (error || !auth.user) throw new HttpError(401, "UNAUTHENTICATED");
  if (!auth.user.email_confirmed_at || !auth.user.email) throw new HttpError(403, "VERIFIED_EMAIL_REQUIRED");
  if (!verifyOnboardingNonce(input.nonce, auth.user.id)) throw new HttpError(403, "ONBOARDING_NONCE_INVALID");
  const admin = adminDb();
  const existing = await admin.from("users").select("tenant_id,role").eq("id", auth.user.id).maybeSingle();
  if (existing.error) databaseError(existing.error);
  if (existing.data) {
    if (existing.data.role !== "hr_admin" || !existing.data.tenant_id) throw new HttpError(409, "ROLE_CONFLICT");
    return json({ tenant_id: existing.data.tenant_id, created: false }, 200);
  }
  const tenant = await admin.rpc("provision_tenant", { p_auth_user: auth.user.id, p_name: input.companyName });
  if (tenant.error) databaseError(tenant.error);
  const lead = await admin.from("leads").insert({ email: auth.user.email.toLowerCase(), company_name: input.companyName,
    status: "trial", tenant_id: tenant.data, consent_at: new Date().toISOString() });
  if (lead.error) databaseError(lead.error);
  return json({ tenant_id: tenant.data, created: true }, 201);
}, { mutation: true });
